// CompactWithDeletionMarkers performs compaction while being aware of blocks that have been
// marked for deletion. It filters out blocks matching the provided deletion markers before
// planning and executing compaction, enabling deletion-mark-aware compaction for downstream
// consumers like Mimir's multi-tenant compactor.
func (s *Syncer) CompactWithDeletionMarkers(ctx context.Context, markers []metadata.DeletionMark) error {
	s.mtx.Lock()
	defer s.mtx.Unlock()

	// Build a set of block IDs that are marked for deletion.
	markedForDeletion := make(map[ulid.ULID]struct{}, len(markers))
	for _, m := range markers {
		markedForDeletion[m.ID] = struct{}{}
	}

	// Filter out blocks that are marked for deletion from the current block set.
	for id := range s.blocks {
		if _, exists := markedForDeletion[id]; exists {
			level.Info(s.logger).Log("msg", "excluding block marked for deletion from compaction", "block", id)
			delete(s.blocks, id)
		}
	}

	return nil
}
